import networkx as nx
import itertools
import random

def get_min_edges_subgraph(G, k):
    nodes = list(G.nodes())
    min_edges = float('inf')
    for J in itertools.combinations(nodes, k):
        edges = G.subgraph(J).number_of_edges()
        if edges < min_edges:
            min_edges = edges
    return min_edges

def test_S(S):
    G = nx.Graph()
    G.add_nodes_from(range(15))
    for i in range(15):
        for s in S:
            G.add_edge(i, (i + s) % 15)

    # Add edges to reach 49
    current_edges = G.number_of_edges()
    while current_edges < 49:
        u, v = random.sample(range(15), 2)
        if not G.has_edge(u, v):
            G.add_edge(u, v)
            current_edges += 1
    return get_min_edges_subgraph(G, 8)

S_list = [{1, 2, 3}, {1, 2, 4}, {1, 3, 4}, {1, 2, 5}, {1, 3, 5}]
for S in S_list:
    best_for_S = 0
    for _ in range(10):
        best_for_S = max(best_for_S, test_S(S))
    print(f"S={S}, best_min_e={best_for_S}")

