import networkx as nx
import itertools
import random

def get_max_edges_subgraph(G, k):
    nodes = list(G.nodes())
    max_edges = 0
    for J in itertools.combinations(nodes, k):
        edges = G.subgraph(J).number_of_edges()
        if edges > max_edges:
            max_edges = edges
    return max_edges

def search_for_graph(k2, max_allowed_e):
    for _ in range(1000):
        G = nx.gnm_random_graph(15, k2)
        if get_max_edges_subgraph(G, 8) <= max_allowed_e:
            return True
    return False

print(f"Exists graph k2=56, max_e=15: {search_for_graph(56, 15)}")
